import{_ as t,o as a,c as s,a4 as i}from"./chunks/framework.DA9C4Pbl.js";const g=JSON.parse('{"title":"Receiving transient alerts (NASA GCN)","description":"","frontmatter":{"title":"Receiving transient alerts (NASA GCN)","visibility":"public","audience":"operator","tier":"guide","source":"handwritten"},"headers":[],"relativePath":"guides/operating/transient-alerts.md","filePath":"guides/operating/transient-alerts.md"}'),n={name:"guides/operating/transient-alerts.md"};function r(o,e,d,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="receiving-transient-alerts-nasa-gcn" tabindex="-1">Receiving transient alerts (NASA GCN) <a class="header-anchor" href="#receiving-transient-alerts-nasa-gcn" aria-label="Permalink to “Receiving transient alerts (NASA GCN)”">​</a></h1><p>Your installation can listen to NASA&#39;s <a href="https://gcn.nasa.gov" target="_blank" rel="noreferrer">General Coordinates Network</a> (GCN), the stream over which space observatories announce transient events — gamma-ray bursts from Swift and SVOM, X-ray transients from Einstein Probe. Alerts arrive as database rows within seconds of the satellite&#39;s downlink and feed the Target-of-Opportunity features as they land in upcoming releases.</p><p>The service is optional. If you skipped it during <code>arcsecond setup</code>, re-run:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --with-alerts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><h2 id="network-prerequisites" tabindex="-1">Network prerequisites <a class="header-anchor" href="#network-prerequisites" aria-label="Permalink to “Network prerequisites”">​</a></h2><p>The consumer opens outbound, encrypted connections to five names, and listens on nothing:</p><table tabindex="0"><thead><tr><th>Name</th><th>Port</th><th>What for</th></tr></thead><tbody><tr><td><code>auth.gcn.nasa.gov</code></td><td>443</td><td>signing in</td></tr><tr><td><code>kafka.gcn.nasa.gov</code></td><td>9092</td><td>the first contact, which hands out the three names below</td></tr><tr><td><code>kafka1.gcn.nasa.gov</code>, <code>kafka2.gcn.nasa.gov</code>, <code>kafka3.gcn.nasa.gov</code></td><td>9092</td><td>the alerts themselves</td></tr></tbody></table><p>That is the complete list to hand your IT department if the observatory network is restricted. Note the port: <code>9092</code> is not a web port, and a network that only lets web traffic out blocks it. It cannot go through a web proxy.</p><h2 id="get-your-gcn-credentials-about-two-minutes-once-per-installation" tabindex="-1">Get your GCN credentials (about two minutes, once per installation) <a class="header-anchor" href="#get-your-gcn-credentials-about-two-minutes-once-per-installation" aria-label="Permalink to “Get your GCN credentials (about two minutes, once per installation)”">​</a></h2><p>GCN identifies each consumer individually — there are no shared Arcsecond credentials. Your installation gets its own identity, its own quota, and its own revocation switch.</p><ol><li>Sign in (or create an account) at <a href="https://gcn.nasa.gov/quickstart" target="_blank" rel="noreferrer">https://gcn.nasa.gov/quickstart</a>.</li><li>Follow the <em>Start streaming GCN Notices</em> flow to create <strong>client credentials</strong>. When asked for a scope, select <strong><code>gcn.nasa.gov/kafka-public-consumer</code></strong>.</li><li>Copy the <strong>client ID</strong> and <strong>client secret</strong> it shows you.</li></ol><h2 id="configure" tabindex="-1">Configure <a class="header-anchor" href="#configure" aria-label="Permalink to “Configure”">​</a></h2><p>Open the <code>.env</code> file in your Arcsecond folder and paste the two values:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GCN_CONSUMER_CLIENT_ID=your-client-id</span></span>
<span class="line"><span>GCN_CONSUMER_CLIENT_SECRET=your-client-secret</span></span></code></pre></div><p>Then recreate just the alerts service, so it reads them:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alerts</span></span></code></pre></div><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to “Verify”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alerts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre></div><p>Within about a minute you should see:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GCN consumer started (group.id=io.arcsecond.local.…, 32 topics).</span></span>
<span class="line"><span>GCN connection established (heartbeat received).</span></span></code></pre></div><p>The heartbeat line repeats at most once per hour — that is the liveness signal. Real alerts are rare; a quiet log between heartbeats is normal and correct. Ctrl-C leaves the log; the service keeps running.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Meaning and next action</th></tr></thead><tbody><tr><td><code>arcsecond status</code> does not list <code>alerts</code></td><td>The service is not in your <code>docker-compose.yml</code>. Run <code>arcsecond setup --with-alerts</code>, then <code>arcsecond start</code>.</td></tr><tr><td>Log says <code>GCN credentials not configured — transient alerts disabled</code></td><td>The two <code>.env</code> keys are empty. Follow <em>Configure</em> above, then <code>arcsecond restart alerts</code>.</td></tr><tr><td>Repeated authentication/SASL errors in the log</td><td>GCN rejected your credentials. Re-create them at <a href="https://gcn.nasa.gov/quickstart" target="_blank" rel="noreferrer">https://gcn.nasa.gov/quickstart</a> (check the scope is <code>gcn.nasa.gov/kafka-public-consumer</code>), update <code>.env</code>, then <code>arcsecond restart alerts</code>.</td></tr><tr><td>Connected, but no heartbeat line</td><td>An outbound connection to the names above is likely blocked, most often port 9092. Test from the host: <code>curl -sI https://auth.gcn.nasa.gov</code>, then <code>curl -v telnet://kafka.gcn.nasa.gov:9092</code> (it must say <em>Connected</em>).</td></tr><tr><td>Log says <code>Installation not initialized</code></td><td>The backend has not completed its first boot yet. Run <code>arcsecond start</code>, which waits for the backend to be ready, then <code>arcsecond restart alerts</code>.</td></tr></tbody></table><h2 id="turning-it-off" tabindex="-1">Turning it off <a class="header-anchor" href="#turning-it-off" aria-label="Permalink to “Turning it off”">​</a></h2><p>Remove the service from your installation; the next start takes its container down:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --without-alerts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>Your GCN credentials stay in <code>.env</code>; delete the two lines (and revoke the credential on gcn.nasa.gov) if you want them gone for good. <code>arcsecond setup --with-alerts</code> brings the service back at any time.</p>`,27)])])}const k=t(n,[["render",r]]);export{g as __pageData,k as default};
